repro_cmds:
cat > /tmp/w1_fd_probe.py <<'PY'
import socket, sys, time, json
SOCK='/run/envh-ctf/ctl.sock'
label=sys.argv[1] if len(sys.argv)>1 else 'probe'; timeout=float(sys.argv[2]) if len(sys.argv)>2 else 3.0
s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); s.settimeout(timeout); t=time.time()
try: s.connect(SOCK)
except OSError as e:
    print(f'PROBE[{label}] connect FAILED {time.time()-t:.3f}s: {e}'); sys.exit(0)
try:
    s.sendall(b'{"op":"list"}\n'); buf=b''
    while b'\n' not in buf:
        c=s.recv(65536)
        if not c: print(f'PROBE[{label}] EOF {time.time()-t:.3f}s'); sys.exit(0)
        buf+=c
    print(f'PROBE[{label}] reply ok={json.loads(buf.split(chr(10).encode(),1)[0]).get("ok")} in {time.time()-t:.3f}s')
except socket.timeout: print(f'PROBE[{label}] TIMEOUT {time.time()-t:.3f}s <-- broker could NOT service')
finally: s.close()
PY
